// 全ての選択肢を試し，正しく判定できるものがちょうど1つかを確かめる
const conds = {
  'a[i] ＜ a[i ＋ 1]': (x, y) => x < y,
  'a[i] ≦ a[i ＋ 1]': (x, y) => x <= y,
  'a[i] ＞ a[i ＋ 1]': (x, y) => x > y,
  'a[i] ≧ a[i ＋ 1]': (x, y) => x >= y,
};
const tests = [[[2, 5, 5, 8], true], [[3, 9, 4], false], [[1, 2, 3], true], [[7, 7], true], [[5, 1], false]];
const ok = [];
for (const [text, cond] of Object.entries(conds)) {
  const isSorted = (a) => {
    for (let i = 1; i <= a.length - 1; i++) if (cond(a[i - 1], a[i])) return false;
    return true;
  };
  if (tests.every(([a, want]) => isSorted(a) === want)) ok.push(text);
}
return ok.length === 1 ? ok[0] : 'answers=' + ok.length;
